#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void depthwise_conv2d_fp16_kernel(
    const __half* __restrict__ input,
    const __half* __restrict__ weight,
    const __half* __restrict__ bias,
    __half* __restrict__ output,
    int N,
    int C,
    int H,
    int W,
    int K,
    int stride,
    int padding,
    int H_out,
    int W_out)
{
    int out_x = blockIdx.x * blockDim.x + threadIdx.x;
    int out_y = blockIdx.y * blockDim.y + threadIdx.y;
    int nz = blockIdx.z;                     // combined batch & channel index
    if (out_x >= W_out || out_y >= H_out) return;

    int n = nz / C;
    int c = nz % C;

    float sum = 0.0f;
    for (int ky = 0; ky < K; ++ky) {
        int in_y = out_y * stride - padding + ky;
        if (in_y < 0 || in_y >= H) continue;
        for (int kx = 0; kx < K; ++kx) {
            int in_x = out_x * stride - padding + kx;
            if (in_x < 0 || in_x >= W) continue;
            int input_idx = ((n * C + c) * H + in_y) * W + in_x;
            int weight_idx = (c * K + ky) * K + kx;
            __half i_val = input[input_idx];
            __half w_val = weight[weight_idx];
            sum += __half2float(i_val) * __half2float(w_val);
        }
    }
    if (bias != nullptr) {
        sum += __half2float(bias[c]);
    }
    int out_idx = ((n * C + c) * H_out + out_y) * W_out + out_x;
    output[out_idx] = __float2half(sum);
}

torch::Tensor depthwise_conv2d_fp16(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding)
{
    const auto N = input.size(0);
    const auto C = input.size(1);
    const auto H = input.size(2);
    const auto W = input.size(3);
    const auto K = weight.size(1); // weight shape (C, K, K)

    const int H_out = (H + 2 * padding - K) / stride + 1;
    const int W_out = (W + 2 * padding - K) / stride + 1;

    auto output = torch::empty({N, C, H_out, W_out}, input.options());

    const dim3 block(16, 16);
    const dim3 grid(
        (W_out + block.x - 1) / block.x,
        (H_out + block.y - 1) / block.y,
        N * C
    );

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "depthwise_conv2d_fp16_kernel", ([&] {
        depthwise_conv2d_fp16_kernel<scalar_t><<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
            reinterpret_cast<const __half*>(input.data_ptr<scalar_t>()),
            reinterpret_cast<const __half*>(weight.data_ptr<scalar_t>()),
            bias.defined() ? reinterpret_cast<const __half*>(bias.data_ptr<scalar_t>()) : nullptr,
            reinterpret_cast<__half*>(output.data_ptr<scalar_t>()),
            N, C, H, W, K, stride, padding, H_out, W_out
        );
    }));

    return output;
}
