    def forward(ctx, input, weight, bias, stride, padding):
        ctx.save_for_backward(input, weight, bias)
        ctx.stride = stride
        ctx.padding = padding
        return extension.depthwise_conv2d_fp16(input, weight, bias, stride, padding)

    @staticmethod
    def backward(ctx, grad_output):
        # Simple fallback to PyTorch's autograd for correctness.
        input, weight, bias = ctx.saved_tensors
        stride = ctx.stride
        padding = ctx.padding
        # Use built‑in depthwise conv for gradients.
        grad_input = grad_weight = grad_bias = None

        if ctx.needs_input_grad[0]:
            grad_input = torch.nn.grad.conv2d_input(
                input.shape, weight, grad_output,
                stride=stride, padding=padding, dilation=1, groups=input.shape[1]
            )
        if ctx.needs_input_grad[1]:
            grad_weight = torch.nn.grad.conv2d_weight(
                input, weight.shape, grad_output,
                stride=stride, padding=padding, dilation=1, groups=input.shape[1]
            )
        if bias is not None and ctx.needs_input_grad[2]:
            grad_bias = grad_output.sum(dim=[0, 2, 3])
        return grad_input, grad_weight, grad_bias, None, None

class ModelNew(nn.Module):
    """
    Drop‑in replacement for the reference depthwise Conv2d using a custom CUDA kernel.
    """
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.bias_flag = bias

        # weight shape: (C, K, K) as depthwise kernel
        self.weight = nn.Parameter(
            torch.randn(in_channels, kernel_size, kernel_size, dtype=torch.float16)
        )
        if bias:
            self.bias = nn.Parameter(torch.randn(in_channels, dtype=torch.float16))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure half precision
        x = x.to(dtype=torch.float16)
        return DepthwiseConv2dFunction.apply(x, self.weight, self.bias,
                                             self.stride, self.padding)

